"tick":{perd:[["mico",{"en":"Leaps over Tick's delayed mines while invulnerable, lands at melee range, and bursts down his low health."}],["mortis",{"en":"Dashes around Tick's delayed mines, closes on his low health, and unloads point-blank before the mines detonate.","fr":"Contourne en ruée les mines différées de Tick, fond sur ses faibles PV et décharge à bout portant avant que les mines ne sautent."}],["darryl",{"en":"Rolls across Tick's minefield with damage reduction, then unloads point-blank shells into his low health."}],["bibi",{"en":"Crosses Tick's delayed minefield with tank health and fast movement, then batters his low health at close range.","fr":"Traverse le champ de mines différées de Tick grâce à ses PV de tank et sa vitesse, puis matraque ses faibles PV au corps à corps."}],["kenji",{"en":"Dashes through gaps in Tick's delayed minefield, then heals through close-range attacks while overwhelming his low health. Also weak to: Thrower Tank","fr":"Se faufile en ruée dans les trous du champ de mines différées de Tick, puis se soigne à coups rapprochés en submergeant ses faibles PV. Également faible face à : Lanceur, Tank"}]],bat:[["juju",{"en":"Controls open-ground lanes beyond Juju's standard artillery reach with lingering mines that force her back.","fr":"Contrôle les couloirs à découvert hors de la portée d'artillerie habituelle de Juju avec des mines persistantes qui la repoussent."}],["kit",{"en":"Keeps Kit outside his effective range with persistent mines, while Last Hurrah absorbs and punishes his committed dive."}],["larry",{"en":"Outranges Larry with lingering mines that arc over walls, control retreat paths, and disrupt his repositioning."}],["mandy",{"en":"Forces Mandy out of Focus with mines lobbed over walls, repeatedly denying her long-range firing lanes."}],["mrp",{"en":"Bombards Mr P and his porter base from artillery range, sustaining lane pressure with rapid mine volleys.","fr":"Bombarde Mr. P et sa base de porteurs à portée d'artillerie, entretenant la pression sur le couloir par des volées de mines rapides.","es":"Bombardea a Mr. P y su base de maleteros desde el alcance de artillería, manteniendo la presión en el carril con andanadas rápidas de minas."}],["nani",{"en":"Bombards Nani from behind walls, denying clean sightlines while frequent mine volleys blanket her approach.","fr":"Bombarde Nani derrière les murs, lui refusant des lignes de vue dégagées pendant que des volées de mines fréquentes saturent son approche.","es":"Bombardea a Nani tras los muros, negándole líneas de visión limpias mientras andanadas frecuentes de minas cubren su acercamiento."}]]},
